changeSet.sql:
ALTER TABLE composer_transcript_part ADD COLUMN answer bytea;
ALTER TABLE composer_transcript_part ADD CONSTRAINT ck_composer_transcript_part_answer
    CHECK (answer IS NULL OR kind = 'SERVED');
CREATE FUNCTION clear_composer_answers() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE composer_transcript_part SET answer = NULL
     WHERE run_id = OLD.id AND workspace_id = OLD.workspace_id AND lease_epoch = OLD.lease_epoch
       AND answer IS NOT NULL;
    RETURN NULL;
END $$;
CREATE TRIGGER agent_run_clears_composer_answers AFTER UPDATE OF state, lease_epoch ON agent_run
    FOR EACH ROW
    WHEN (OLD.kind = 'REVIEW_COMPOSE' AND OLD.state = 'LEASED'
          AND (NEW.state <> 'LEASED' OR NEW.lease_epoch <> OLD.lease_epoch))
    EXECUTE FUNCTION clear_composer_answers();

changeSet.rollback:
DROP TRIGGER agent_run_clears_composer_answers ON agent_run;
DROP FUNCTION clear_composer_answers();
ALTER TABLE composer_transcript_part DROP CONSTRAINT ck_composer_transcript_part_answer;
ALTER TABLE composer_transcript_part DROP COLUMN answer;
